name: Approve workflows for first‑time contributors

permissions:
  contents: read

on:
  pull_request_target:
    types: [labeled, synchronize]
    branches: [main, release-**]

jobs:
  approve:
    if: github.event.pull_request.head.repo.full_name == github.repository
    runs-on: ubuntu-latest
    permissions:
      actions: write
    steps:
      - name: Determine if contributor is returning or has ok‑to‑test label
        id: approval
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const author = pr.user.login;
            const labels = pr.labels.map(l => l.name);
            const hasOkToTest = labels.includes('ok-to-test');

            // Count closed PRs by the author
            const query = `repo:${owner}/${repo} author:${author} type:pr state:closed`;
            const result = await github.request('GET /search/issues', {
              q: query,
              per_page: 100
            });
            const totalPRs = result.data.total_count;
            const isReturning = totalPRs > 1;

            core.setOutput('has_ok_to_test', hasOkToTest);
            core.setOutput('is_returning', isReturning);

      - name: Approve pending workflow runs
        if: steps.approval.outputs.is_returning == 'true' || steps.approval.outputs.has_ok_to_test == 'true'
        uses: actions/github-script@v6
        with:
          script: |
            const pr = context.payload.pull_request;
            const owner = context.repo.owner;
            const repo = context.repo.repo;
            const headSha = pr.head.sha;

            // List all workflow runs for this PR
            const runs = await github.paginate('GET /repos/{owner}/{repo}/actions/runs', {
              owner,
              repo,
              per_page: 100,
              head_sha: headSha,
              event: 'pull_request'
            });

            for (const run of runs) {
              if (run.status === 'pending' && run.conclusion === 'action_required') {
                await github.request('POST /repos/{owner}/{repo}/actions/runs/{run_id}/enable', {
                  owner,
                  repo,
                  run_id: run.id
                });
                console.log(`Approved workflow run ${run.id}`);
              }
            }
